*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-page:        #0f1117;
  --bg-card:        #1a1d27;
  --bg-input:       #12141e;
  --border-default: #2e3147;
  --border-focus:   #6c63ff;
  --border-error:   #e05252;
  --text-primary:   #e8eaf0;
  --text-secondary: #8b8fa8;
  --text-label:     #c4c6d4;
  --accent:         #6c63ff;
  --accent-hover:   #8077ff;
  --accent-active:  #574fd6;
  --required-star:  #e05252;
  --success-bg:     #1a2e22;
  --success-border: #34a853;
  --success-text:   #6fcf97;
  --radius:         10px;
  --transition:     200ms ease;
}

body {
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  background: var(--bg-page);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

/* ── Card ── */
.support-card {
  width: 100%;
  max-width: 520px;
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: 16px;
  padding: clamp(1.5rem, 5vw, 2.5rem);
  box-shadow: 0 8px 40px rgba(0, 0, 0, .55);
}

.support-card__eyebrow {
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .12em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: .4rem;
}

.support-card__title {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: .5rem;
  line-height: 1.2;
}

.support-card__description {
  font-size: .9rem;
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
}

/* ── Form ── */
.contact-form { display: flex; flex-direction: column; gap: 1.25rem; }

/* ── Field wrapper ── */
.form-field { display: flex; flex-direction: column; gap: .375rem; }

.form-field__label {
  font-size: .875rem;
  font-weight: 500;
  color: var(--text-label);
  display: flex;
  align-items: center;
  gap: .25rem;
}

.form-field__required {
  color: var(--required-star);
  font-weight: 700;
  aria-hidden: true;
}

.form-field__optional {
  font-size: .75rem;
  font-weight: 400;
  color: var(--text-secondary);
  margin-left: .15rem;
}

/* ── Inputs ── */
.form-field__input {
  width: 100%;
  padding: .65rem .9rem;
  background: var(--bg-input);
  border: 1.5px solid var(--border-default);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: .95rem;
  font-family: inherit;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
  /* Ensure transparent outline visible in forced-colors */
  outline: 2px solid transparent;
  outline-offset: 2px;
}

.form-field__input::placeholder { color: var(--text-secondary); opacity: 1; }

.form-field__input:hover:not(:disabled) {
  border-color: #454870;
}

.form-field__input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(108, 99, 255, .25);
  outline: 2px solid var(--border-focus);
}

/* Invalid state (applied via JS after first submit attempt) */
.form-field__input[aria-invalid="true"] {
  border-color: var(--border-error);
  box-shadow: 0 0 0 3px rgba(224, 82, 82, .2);
}

.form-field__input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(224, 82, 82, .3);
  outline-color: var(--border-error);
}

/* ── Helper / error text ── */
.form-field__helper {
  font-size: .8rem;
  color: var(--text-secondary);
  display: flex;
  align-items: flex-start;
  gap: .3rem;
}

.form-field__error {
  font-size: .8rem;
  color: var(--border-error);
  display: none;        /* hidden until validation triggers */
  align-items: flex-start;
  gap: .3rem;
}

.form-field__error[data-visible="true"] { display: flex; }

/* ── Submit button ── */
.btn-submit {
  margin-top: .25rem;
  padding: .75rem 1.25rem;
  background: var(--accent);
  color: #fff;
  font-size: .95rem;
  font-weight: 600;
  font-family: inherit;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition),
              box-shadow var(--transition);
  outline: 2px solid transparent;
  outline-offset: 2px;
  width: 100%;
}

.btn-submit:hover { background: var(--accent-hover); }
.btn-submit:active { background: var(--accent-active); transform: translateY(1px); }
.btn-submit:focus-visible {
  outline: 2px solid var(--border-focus);
  box-shadow: 0 0 0 4px rgba(108, 99, 255, .3);
}
.btn-submit:disabled { opacity: .55; cursor: not-allowed; }

/* ── Success message ── */
.success-banner {
  display: none;
  align-items: flex-start;
  gap: .75rem;
  background: var(--success-bg);
  border: 1px solid var(--success-border);
  border-radius: var(--radius);
  padding: 1rem 1.1rem;
  color: var(--success-text);
  font-size: .9rem;
  margin-top: .25rem;
}
.success-banner[data-visible="true"] { display: flex; }
.success-banner__icon { flex-shrink: 0; margin-top: .1rem; }

/* ── Required legend ── */
.form-legend {
  font-size: .78rem;
  color: var(--text-secondary);
  margin-top: -.5rem;
  margin-bottom: .25rem;
}
.form-legend .star { color: var(--required-star); }

/* ── Forced colors ── */
@media (forced-colors: active) {
  .form-field__input { border: 2px solid ButtonBorder; color: CanvasText; background: Canvas; }
  .form-field__input:focus { outline: 2px solid Highlight; }
  .btn-submit { forced-color-adjust: none; }
}

/* ── Reflow at 320 px ── */
@media (max-width: 360px) {
  .support-card { border-radius: 0; border-left: none; border-right: none; }
}
