// ── Field component ───────────────────────────────────────────────────────────

/**
 * Creates a labelled text field wrapped in .form-field.
 *
 * @param {object} opts
 * @param {string}  opts.id
 * @param {string}  opts.label
 * @param {string}  opts.type
 * @param {string}  opts.autocomplete
 * @param {string}  opts.placeholder
 * @param {boolean} opts.required
 * @param {string}  [opts.helperText]   - always-visible hint
 * @param {string}  [opts.errorText]    - shown only on invalid+submitted
 * @param {string}  [opts.inputmode]
 * @returns {{ wrapper: HTMLElement, input: HTMLInputElement, errorEl: HTMLElement }}
 */
function Field({ id, label, type, autocomplete, placeholder, required,
                  helperText, errorText, inputmode }) {

  const helperId = helperText  ? `${id}-helper` : null;
  const errorId  = errorText   ? `${id}-error`  : null;

  const describedBy = [helperId, errorId].filter(Boolean).join(' ') || null;

  const inputAttrs = {
    id,
    type,
    name: id,
    className: 'form-field__input',
    placeholder,
    autocomplete,
    ...(required            ? { required: '' }          : {}),
    ...(inputmode           ? { inputmode }              : {}),
    ...(describedBy         ? { 'aria-describedby': describedBy } : {}),
