    label,
    required
      ? el('span', { className: 'form-field__required', 'aria-hidden': 'true' }, ' *')
      : el('span', { className: 'form-field__optional' }, '(optional)')
  );

  const helperNode = helperText
    ? el('p', { id: helperId, className: 'form-field__helper' }, helperText)
    : null;

  const errorNode = errorText
    ? el('p', { id: errorId, className: 'form-field__error', role: 'alert',
                'aria-live': 'polite' }, errorText)
    : null;

  const wrapper = el('div', { className: 'form-field' },
    labelNode,
    input,
    helperNode,
    errorNode,
  );

  return { wrapper, input, errorEl: errorNode };
}

// ── ContactForm component ─────────────────────────────────────────────────────

function ContactForm() {
  let submitted = false;

  // Build fields
  const nameField = Field({
    id:           'full-name',
    label:        'Full Name',
    type:         'text',
    autocomplete: 'name',
    placeholder:  'Jane Smith',
    required:     true,
    errorText:    'Please enter your full name.',
  });

  const emailField = Field({
    id:           'email',
    label:        'Email Address',
    type:         'email',
    autocomplete: 'email',
    placeholder:  'jane@example.com',
    required:     true,
    errorText:    'Please enter a valid email address.',
  });

  const phoneField = Field({
    id:           'phone',
    label:        'Phone Number',
    type:         'tel',
    autocomplete: 'tel',
    placeholder:  '+1 (555) 000-0000',
    required:     false,
    inputmode:    'tel',
    helperText:   'Format: +1 (555) 000-0000 — country code followed by area code and number.',
    errorText:    'Please enter a valid phone number (digits, spaces, +, –, parentheses only).',
  });

  // Validation rules
  const PHONE_RE = /^[+\d][\d\s\-().]{6,19}$/;

  function validate(field) {
    const { input, errorEl } = field;
    if (!errorEl) return true;

    let valid = true;
    if (input.required && !input.value.trim()) {
      valid = false;
    } else if (input.type === 'email' && input.value.trim() &&
               !input.validity.valid) {
      valid = false;
    } else if (input.id === 'phone' && input.value.trim() &&
               !PHONE_RE.test(input.value.trim())) {
      valid = false;
