  function attachLiveValidation(field) {
    field.input.addEventListener('input', () => {
      if (submitted) validate(field);
    });
    field.input.addEventListener('blur', () => {
      if (submitted) validate(field);
    });
  }

  [nameField, emailField, phoneField].forEach(attachLiveValidation);

  // Success banner
  const successBanner = el('div', {
    className: 'success-banner',
    role:      'status',
    'aria-live': 'polite',
  },
    el('svg', {
      className: 'success-banner__icon',
      width: '20', height: '20', viewBox: '0 0 20 20',
      fill: 'none', 'aria-hidden': 'true',
    },
      (() => {
        const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        circle.setAttribute('cx', '10'); circle.setAttribute('cy', '10');
        circle.setAttribute('r', '9'); circle.setAttribute('stroke', '#34a853');
        circle.setAttribute('stroke-width', '1.5');
        const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
        path.setAttribute('d', 'M6 10l3 3 5-5');
        path.setAttribute('stroke', '#34a853'); path.setAttribute('stroke-width', '1.8');
        path.setAttribute('stroke-linecap', 'round'); path.setAttribute('stroke-linejoin', 'round');
        const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
        g.append(circle, path);
        return g;
      })()
    ),
    el('span', {}, "Thanks! We've received your message and will be in touch shortly.")
  );

  // Submit button
  const submitBtn = el('button', {
    type:      'submit',
    className: 'btn-submit',
  }, 'Send Message');

  // Form element
  const form = el('form', {
    id:        'contact-form',
    className: 'contact-form',
    novalidate: '',
    'aria-label': 'Contact support',
  },
    el('p', { className: 'form-legend' },
      el('span', { className: 'star', 'aria-hidden': 'true' }, '* '),
      'Required fields'
    ),
    nameField.wrapper,
    emailField.wrapper,
    phoneField.wrapper,
    submitBtn,
    successBanner,
  );

  form.addEventListener('submit', e => {
    e.preventDefault();
    submitted = true;

    const fields   = [nameField, emailField, phoneField];
    const validity = fields.map(validate);
    const allValid = validity.every(Boolean);

    if (!allValid) {
      // Focus first invalid input
      const firstInvalid = fields.find((_, i) => !validity[i]);
      firstInvalid.input.focus();
      return;
    }

    // Success — disable form, show banner
    submitBtn.disabled = true;
    form.querySelectorAll('input').forEach(i => { i.disabled = true; });
    successBanner.dataset.visible = 'true';
    successBanner.focus();
  });

  return form;
}

// ── Mount ─────────────────────────────────────────────────────────────────────

(function mount() {
  const root = document.getElementById('contact-form-root');
  if (!root) return;
  root.appendChild(ContactForm());
})();
